		os.Exit(1)
	}

	// Get the free space in bytes
	freeSpaceBytes, err := getFreeSpace(*drive)
	if err != nil {
		fmt.Printf("Error getting free space: %v\n", err)
		os.Exit(1)
	}

	// We are going to write zeros to the root of the drive until we have written freeSpaceBytes
	// We'll create a file in the root and write zeros until the drive is full.

	// We need to write to the drive, so we'll use the root directory and then write to a file.
	// Let's create a file named "filler" in the root, but note that we are going to fill the entire drive, so we might need to create multiple files.

	// We'll write to a file until we have written the free space, but we must be cautious because the drive might have multiple files and we cannot write to all of them.

	// Alternatively, we can write to the root and then to every subdirectory we can, but that is more complex.

	// Let's just write to one file and keep writing until the drive is full. But note: the file we are writing might be limited by the file system (like maximum file size). We can use a large buffer and write multiple times.

	// We'll write to a file in the root, but if the free space is large, we might need to create multiple files.

	// We can do: create a file in the root, then if we cannot write more (because of file size limits), we can create a new file and continue.

	// But note: the maximum file size in Windows is 2^63-1 bytes, so we can write the entire free space in one file if it's less than that.

	// Let's assume the free space is less than 2^63-1 bytes.

	// We'll write zeros to a file until we have written the free space.

	// However, we must be cautious because the drive might be in use and we might not be able to write the entire free space. Also, we are going to use the root directory, which might be protected.

	// We'll use the drive root and write to a file named "filler_<drive>_<time>.txt" to avoid conflicts.

	// But note: we are going to fill the drive, so we don't care about the file name.

	// Let's create the file and write zeros until we have written the free space.

	fileName := fmt.Sprintf("filler_%s_%d.txt", *drive, time.Now().Unix())

	// Open the file for writing
	file, err := os.Create(fileName)
	if err != nil {
		fmt.Printf("Error creating file: %v\n", err)
		os.Exit(1)
	}
	defer file.Close()

	// We'll write zeros until we have written freeSpaceBytes
	buffer := make([]byte, 4096) // 4KB buffer
	written := int64(0)
	totalToWrite := freeSpaceBytes

	for written < totalToWrite {
		n, err := file.Write(buffer)
		if err != nil {
			fmt.Printf("Error writing to file: %v\n", err)
			os.Exit(1)
		}
		written += int64(n)
		if written >= totalToWrite {
			break
		}
	}

	fmt.Printf("Wrote %d bytes to %s. The drive %s should now be full.\n", written, fileName, *drive)
